<script>
 import {onMount} from 'svelte';
 import GraphCanvas from './GraphCanvas.svelte';
 import Icon from './Icon.svelte';
 import {regions,artists,items,item,typeName,targets,relatedResources,makeGraph,initialState} from './model.js';
 let draft=$state(initialState());
 let view=$state('map'),focus=$state(''),selected=$state(''),query=$state(''),note=$state(''),notice=$state(''),target=$state(targets[0].id);
 const current=$derived(item(selected));
 const graph=$derived(makeGraph(focus,draft.positions));
 const matches=$derived(query.trim()?items.filter(n=>n.name.toLowerCase().includes(query.toLowerCase())).slice(0,8):[]);
 const selectedItems=$derived(draft.planIds.map(item).filter(Boolean));
 const notes=$derived(draft.annotations.filter(n=>n.targetId===selected));
 function readLocation(){const p=new URLSearchParams(location.search);view=['map','report','campaign'].includes(p.get('view'))?p.get('view'):'map';focus=p.get('focus')||'';selected=p.get('select')||'';target=targets.some(t=>t.id===p.get('target'))?p.get('target'):targets[0].id;}
 function navigate(next={}){view=next.view??view;focus=next.focus??focus;selected=next.select??selected;const p=new URLSearchParams();p.set('view',view);if(focus)p.set('focus',focus);if(selected)p.set('select',selected);if(view==='campaign')p.set('target',target);history.pushState({},'',`?${p}`);note='';}
 function select(id){const n=item(id);navigate({view:'map',select:id,focus:n?.kind==='region'||n?.kind==='artist'?id:focus});query='';}
 function togglePlan(id){draft.planIds=draft.planIds.includes(id)?draft.planIds.filter(x=>x!==id):[...draft.planIds,id];}
 function addNote(){if(!note.trim()||!current)return;draft.annotations=[...draft.annotations,{id:crypto.randomUUID(),targetId:selected,text:note.trim(),createdAt:new Date().toISOString()}];note='';notice='Note saved';}
 function saveView(){draft.savedViews=[...draft.savedViews,{id:crypto.randomUUID(),name:current?.name||'All regions',focus,selected}];notice='View saved';}
 function report(){draft.report={id:crypto.randomUUID(),title:draft.report?.title||'Defiant opportunity plan',thesis:draft.report?.thesis||'',createdAt:new Date().toISOString(),findings:selectedItems.map(n=>({id:n.id,name:n.name,kind:n.kind,description:n.description||n.profile||n.subtitle,notes:draft.annotations.filter(a=>a.targetId===n.id).map(a=>a.text)}))};navigate({view:'report'});}
 function createCampaign(){const existing=draft.campaigns.find(c=>c.reportId===draft.report.id&&c.target===target);if(!existing)draft.campaigns=[...draft.campaigns,{id:crypto.randomUUID(),reportId:draft.report.id,target,title:draft.report.title,brief:draft.report.thesis,createdAt:new Date().toISOString()}];navigate({view:'campaign'});}
 function download(){const r=draft.report;const text=`# ${r.title}\n\n${r.thesis}\n\nDesign study: sample data, not verified research.\n\n`+r.findings.map(f=>`## ${f.name}\n${f.description||''}\n${f.notes.map(n=>`- ${n}`).join('\n')}\n`).join('\n');const u=URL.createObjectURL(new Blob([text],{type:'text/markdown'}));const a=document.createElement('a');a.href=u;a.download='defiant-opportunity-plan.md';a.click();URL.revokeObjectURL(u);}
 $effect(()=>{localStorage.setItem('defiant-design-study:v1',JSON.stringify(draft));});
 onMount(()=>{readLocation();});
</script>
<svelte:window onpopstate={readLocation}/>
<header class="topbar"><a href="?view=map" class="wordmark" onclick={(e)=>{e.preventDefault();navigate({view:'map',focus:'',select:''});}}><span class="logo">d.</span> DEFIANT <span class="product">Strategy</span></a><nav aria-label="Workspace"><button class:active={view==='map'} onclick={()=>navigate({view:'map'})}>Explore</button><button class:active={view!=='map'} disabled={!draft.report} onclick={()=>navigate({view:'report'})}>Plan {#if draft.report}<span class="dot"></span>{/if}</button></nav><span class="study">Design study · sample data</span></header>
{#if view==='map'||!draft.report}
<div class="workspace">
 <aside class="rail"><label class="search"><Icon name="search"/><input aria-label="Find an artist, region or resource" placeholder="Find anything…" bind:value={query}/></label>
 {#if query}<div class="search-results">{#each matches as n (n.id)}<button onclick={()=>select(n.id)}><strong>{n.name}</strong><small>{typeName[n.kind]}</small></button>{/each}{#if !matches.length}<p>No matches</p>{/if}</div>{/if}
 <div class="rail-heading">REGIONS <span>{regions.length}</span></div><button class:chosen={!focus} class="rail-item" onclick={()=>navigate({focus:'',select:''})}><Icon name="network"/>All regions</button>
 {#each regions as r (r.id)}<button class="rail-item" class:chosen={focus===r.id||item(focus)?.regionId===r.id} onclick={()=>select(r.id)}><span class="country">{r.country}</span>{r.name}<Icon name="chevron" size={13}/></button>{/each}
 <div class="rail-heading saved-heading">SAVED VIEWS<button aria-label="Save current view" onclick={saveView}><Icon name="plus" size={15}/></button></div>
 {#each draft.savedViews as s (s.id)}<button class="rail-item saved" onclick={()=>navigate({view:'map',focus:s.focus,select:s.selected})}><Icon name="folder" size={15}/>{s.name}</button>{/each}
 {#if !draft.savedViews.length}<p class="rail-hint">Keep a useful perspective.<br/>Save it here to return later.</p>{/if}
 <div class="rail-footer"><span class="avatar">S</span><div>Strategy team<small>Local design workspace</small></div></div></aside>
 <main class="map-area"><div class="map-heading"><div><div class="eyebrow">OPPORTUNITY MAP</div><h1>{focus?item(focus)?.kind==='artist'?item(focus)?.name:`${item(focus)?.name} & beyond`:'Explore regions'}</h1><p>{focus?'Follow a route. Find someone worth bringing into the room.':'Start with a region. Explore the people and connections around it.'}</p></div>{#if focus}<button class="quiet" onclick={()=>navigate({focus:'',select:''})}><Icon name="back"/>All regions</button>{/if}</div>
 <GraphCanvas nodes={graph.nodes} edges={graph.edges} selectedId={selected} onselect={select} onmove={(id,pos)=>{draft.positions={...draft.positions,[id]:pos};}} planIds={draft.planIds}/>
 <div class="plan-tray"><div class="tray-label"><Icon name="folder"/><strong>Your shortlist</strong><span>{selectedItems.length}</span></div><div class="tray-items">{#each selectedItems as n (n.id)}<button title={'Remove '+n.name} onclick={()=>togglePlan(n.id)}>{n.name}<Icon name="close" size={12}/></button>{/each}{#if !selectedItems.length}<span class="muted">Add people, routes or ideas as you explore.</span>{/if}</div><button class="primary" disabled={!selectedItems.length} onclick={report}>Build a plan<Icon name="arrow" size={16}/></button></div></main>
 <aside class="inspector" aria-label="Selection details">{#if current}<div class="inspector-top"><span class="eyebrow">{typeName[current.kind]}</span><button aria-label="Close details" onclick={()=>navigate({select:''})}><Icon name="close"/></button></div><div class="detail-icon"><Icon name={current.kind==='region'?'globe':current.kind==='artist'?'music':current.kind==='route'?'route':'person'} size={25}/></div><h2>{current.name}</h2><p class="subtitle">{current.subtitle}</p><span class="sample-tag">Sample reference</span>
 {#if current.kind==='region'}<h3>Sound & scene</h3><div class="tags">{#each current.tags||[] as tag (tag)}<span>{tag}</span>{/each}</div><h3>Artist to explore</h3>{#each artists.filter(a=>a.regionId===current.id) as a (a.id)}<button class="related" onclick={()=>select(a.id)}><span><strong>{a.name}</strong><small>{a.subtitle}</small></span><Icon name="arrow"/></button>{/each}{/if}
 {#if current.kind==='artist'}<h3>The starting point</h3><p class="body-copy">{current.profile}</p><div class="tags"><span>{current.bpm} BPM</span><span>{item(current.regionId)?.name}</span></div><h3>Possible connections</h3>{#each relatedResources(current.id).slice(0,3) as r (r.id)}<button class="related" onclick={()=>select(r.id)}><span><strong>{r.name}</strong><small>{typeName[r.kind]}</small></span><Icon name="arrow" size={15}/></button>{/each}{/if}
 {#if current.description}<h3>Why this connection</h3><p class="body-copy">{current.description}</p>{/if}
 <button class="add-plan" class:added={draft.planIds.includes(current.id)} onclick={()=>togglePlan(current.id)}><Icon name={draft.planIds.includes(current.id)?'check':'plus'}/>{draft.planIds.includes(current.id)?'On your shortlist':'Add to shortlist'}</button>
 <section class="notes"><h3>Working notes <span>{notes.length}</span></h3>{#each notes as n (n.id)}<article class="note"><p>{n.text}</p><small>Strategy team · local draft</small></article>{/each}<label for="note" class="sr-only">Note about {current.name}</label><textarea id="note" bind:value={note} placeholder="What do you see here?" rows="3"></textarea><button class="quiet note-save" disabled={!note.trim()} onclick={addNote}><Icon name="plus" size={15}/>Add note</button></section><details class="provenance"><summary>Reference details</summary><p>This example comes from the supplied Defiant seed. Relationships, performance and access are unverified.</p><code>{current.sourceId}</code></details>
 {:else}<div class="empty-inspector"><div class="detail-icon"><Icon name="network" size={26}/></div><h2>Select a region</h2><p>Choose a region to find an artist, explore a route and collect what matters.</p><div class="steps"><span>01 <b>Explore a scene</b></span><span>02 <b>Connect the dots</b></span><span>03 <b>Make a plan</b></span></div></div>{/if}</aside>
</div>
{:else if draft.report}
<main class="report-shell"><div class="report-nav"><button class="quiet" onclick={()=>navigate({view:'map'})}><Icon name="back"/>Back to map</button><span>Saved in this browser</span><button class="quiet" onclick={download}><Icon name="download"/>Download brief</button></div>
{#if view==='campaign'}<section class="campaign-confirm"><span class="success-icon"><Icon name="check" size={25}/></span><div class="eyebrow">CAMPAIGN DRAFT</div><h1>Campaign draft created</h1><p>Your plan has been carried into a local campaign draft for <strong>{targets.find(t=>t.id===target)?.name}</strong>.</p><div class="campaign-card"><small>FEED POST · CONCEPT PREVIEW</small><h2>{draft.campaigns.find(c=>c.reportId===draft.report.id&&c.target===target)?.title||draft.report.title}</h2><p>{draft.campaigns.find(c=>c.reportId===draft.report.id&&c.target===target)?.brief||'Add the story angle in your planning report.'}</p><span>DEFIANT RECORDS ↗</span></div><p class="muted">Design study. No account connected and nothing published.</p><button class="primary" onclick={()=>navigate({view:'report'})}>Return to the plan<Icon name="arrow"/></button></section>
{:else}<div class="report-layout"><article class="report-paper"><div class="eyebrow">OPPORTUNITY PLAN · DRAFT</div><input class="report-title" aria-label="Plan title" bind:value={draft.report.title}/><label class="field-label" for="thesis">The idea</label><textarea id="thesis" class="thesis" rows="3" bind:value={draft.report.thesis} placeholder="What should we bring together, and why now?"></textarea><div class="report-section-heading"><h2>Selected findings</h2><span>{draft.report.findings.length}</span></div>{#each draft.report.findings as f (f.id)}<section class="finding"><span class="eyebrow">{typeName[f.kind]}</span><h3>{f.name}</h3><p>{f.description}</p>{#each f.notes as n, i (i)}<blockquote>{n}</blockquote>{/each}<button class="text-link" onclick={()=>select(f.id)}>Explore reference<Icon name="arrow" size={14}/></button></section>{/each}<p class="report-footnote">Snapshot of your shortlist and notes when this report was created. Sample references require research before a real campaign.</p></article><aside class="handoff"><h2>From idea to campaign</h2><p>Choose where this plan belongs. The brief travels with it.</p><label for="target">Campaign account</label><select id="target" bind:value={target}>{#each targets as t (t.id)}<option value={t.id}>{t.name}</option>{/each}</select><small>{targets.find(t=>t.id===target)?.handle}</small><button class="primary" onclick={createCampaign}>Create campaign draft<Icon name="arrow" size={16}/></button><div class="handoff-checklist"><h3>Before this becomes real</h3><p><Icon name="note" size={16}/>Verify sources and fit</p><p><Icon name="person" size={16}/>Confirm participation and rights</p><p><Icon name="calendar" size={16}/>Agree timing with the team</p></div></aside></div>{/if}</main>
{/if}
{#if notice}<button class="toast" onclick={()=>notice=''}><Icon name="check" size={15}/>{notice}<Icon name="close" size={13}/></button>{/if}
